-- ============================================================================
-- 2026-06-04 - Egyhazkozsegek (congregations) seed
-- Forras: dioceses-congregations-seed-2026-04-30-frissitett.xlsx
-- Minden gyulekezet a dioceses ala kotve (diocese_id FK), egyhazmegye-nev alapjan.
-- Idempotens: WHERE NOT EXISTS (nev_hu + diocese_id).
-- ELOTTE fusson: 2026-04-30-dioceses-seed.sql + 2026-06-03b-kiralyhagomelleki-dioceses-seed.sql
-- ============================================================================

BEGIN;

0260-653115', 'daniellugosi@yahoo.com', NULL, now() FROM public.dioceses d JOIN public.districts dt ON d.district_id = dt.id WHERE d.name = 'Zilahi Református Egyházmegye' AND dt.name = 'Királyhágómelléki Református Egyházkerület' AND NOT EXISTS (SELECT 1 FROM public.congregations c WHERE c.nev_hu = 'Kusaly Református Egyházközség' AND c.diocese_id = d.id);
0742-649075', 'tolnamiki@gmail.com', NULL, now() FROM public.dioceses d JOIN public.districts dt ON d.district_id = dt.id WHERE d.name = 'Zilahi Református Egyházmegye' AND dt.name = 'Királyhágómelléki Református Egyházkerület' AND NOT EXISTS (SELECT 1 FROM public.congregations c WHERE c.nev_hu = 'Ördögkút-Cigányi Református Egyházközség' AND c.diocese_id = d.id);
0728-784530', 'szkeva73@yahoo.com
szkizo71@yahoo.com', NULL, now() FROM public.dioceses d JOIN public.districts dt ON d.district_id = dt.id WHERE d.name = 'Zilahi Református Egyházmegye' AND dt.name = 'Királyhágómelléki Református Egyházkerület' AND NOT EXISTS (SELECT 1 FROM public.congregations c WHERE c.nev_hu = 'Szilágycseh Református Egyházközség' AND c.diocese_id = d.id);
0725-573084', 'sulegyulazsolt@freemail.hu', NULL, now() FROM public.dioceses d JOIN public.districts dt ON d.district_id = dt.id WHERE d.name = 'Zilahi Református Egyházmegye' AND dt.name = 'Királyhágómelléki Református Egyházkerület' AND NOT EXISTS (SELECT 1 FROM public.congregations c WHERE c.nev_hu = 'Szilágyszentkirály Református Egyházközség' AND c.diocese_id = d.id);
zilahliget@gmail.com', NULL, now() FROM public.dioceses d JOIN public.districts dt ON d.district_id = dt.id WHERE d.name = 'Zilahi Református Egyházmegye' AND dt.name = 'Királyhágómelléki Református Egyházkerület' AND NOT EXISTS (SELECT 1 FROM public.congregations c WHERE c.nev_hu = 'Zilah-Liget Református Egyházközség' AND c.diocese_id = d.id);

COMMIT;

SELECT dt.name AS egyhazkerulet, d.name AS egyhazmegye, COUNT(c.id) AS gyulekezetek FROM public.dioceses d JOIN public.districts dt ON d.district_id = dt.id LEFT JOIN public.congregations c ON c.diocese_id = d.id GROUP BY dt.name, d.name ORDER BY dt.name, d.name;
